"""Independent read-only lineage, train-only preprocessing, CPU reload and CSV audit."""
import os
for k in ['OMP_NUM_THREADS','OPENBLAS_NUM_THREADS','MKL_NUM_THREADS']:os.environ[k]='1'
from research_w3_common import ROOT,sha,dump,now,compare,gate
import json,numpy as np,pandas as pd,joblib,torch
from threadpoolctl import threadpool_limits
from research_w3_tabm_values import load
def feature_audit(tr,raw):
 num=raw.select_dtypes(include='number').columns.tolist();med=raw[num].median();assert tr.num==num and tr.medians.equals(med);assert tr.columns==list(raw) and tr.cat==list(raw);a=raw[num].fillna(med).to_numpy('float32');assert np.array_equal(tr.mask,np.any(a!=a[0],axis=0));assert tr.qt.get_params()['subsample']==100000 and tr.qt.get_params()['random_state']==42 and tr.qt.get_params()['output_distribution']=='normal'
 for c in raw:
  s=raw[c].fillna(med[c]).astype('int64').astype(str) if c in num else raw[c].fillna('__MISSING__').astype(str);expected={v:i+1 for i,v in enumerate(sorted(s.unique()))};assert tr.vocabs[c]==expected
 assert tr.cardinalities==[len(tr.vocabs[c])+1 for c in raw];before=__import__('hashlib').sha256(__import__('pickle').dumps(tr)).hexdigest();test=raw.iloc[:3].copy();test.loc[:,num]=10**9
 for c in tr.cat:
  if c not in num:test[c]='__NEVER_SEEN_AUDIT__'
 n,c=tr.transform(test);assert np.isfinite(n).all() and np.all(c==0);assert before==__import__('hashlib').sha256(__import__('pickle').dumps(tr)).hexdigest()
 return {'training_rows':len(raw),'numeric_median_and_constant_mask_match':True,'all21_vocabularies_match_exact_outer_training_values':True,'unseen_values_reserved0':True,'transform_does_not_mutate_fitted_state':True,'quantile_config_verified':True}
def main():
 torch.set_num_threads(1);torch.set_num_interop_threads(1);selection=json.loads((ROOT/'research_w3_values_selection.json').read_text());assert selection['eligible_for_full'];batch=selection['batch_size'];train=pd.read_csv(ROOT/'data/train.csv');test=pd.read_csv(ROOT/'data/test.csv');raw=train.drop(columns=['id','satisfaction']);y=train.satisfaction.astype('int8').to_numpy();report={'started_utc':now(),'new_model_fits_performed':False,'primary_and_confirmation':{},'oof':{}}
 with threadpool_limits(1):
  for split,file in [('primary','artifacts/split_seed42.npz'),('confirm','iteration_artifacts/split_confirm20261017.npz')]:
   ix=np.load(ROOT/file);p=ROOT/'research_artifacts'/f'w3_tabm_values_{split}_b{batch}';z=np.load(p/'validation.npz');ref=np.load(ROOT/'research_artifacts'/f'gpu_value_raw_{split}_n2/validation.npz');assert all(np.array_equal(z[k],ref[k]) for k in ['idx','id','target']);assert np.array_equal(z['idx'],ix['valid']) and np.array_equal(z['target'],y[z['idx']]);assert np.array_equal(z['candidate'],.75*ref['candidate']+.25*z['pred']);c=compare(z['target'],ref['candidate'],z['candidate']);assert gate(c,split);tr=joblib.load(p/'fold0/transformer.joblib');report['primary_and_confirmation'][split]={'comparison':c,'feature_audit':feature_audit(tr,raw.iloc[ix['train']])}
  p=ROOT/'research_artifacts'/f'w3_tabm_values_oof_b{batch}';o=np.load(p/'validation.npz');ref=np.load(ROOT/'research_artifacts/gpu_value_raw_oof_n2/oof.npz');folds=np.load(ROOT/'research_artifacts/oof_v1/folds.npz');assert all(np.array_equal(o[k],ref[k]) and np.array_equal(o[k],folds[k]) for k in ['id','target','fold']);assert np.array_equal(o['candidate'],.75*ref['candidate']+.25*o['pred']);c=compare(y,ref['candidate'],o['candidate']);assert gate(c,'oof');report['oof']['comparison']=c;report['oof']['folds']=[]
  for k in range(5):
   vi=np.flatnonzero(o['fold']==k);fi=np.flatnonzero(o['fold']!=k);z=np.load(p/f'fold{k}/validation.npz');assert np.array_equal(z['idx'],vi) and np.array_equal(z['pred'],o['pred'][vi]);c=compare(y[vi],ref['candidate'][vi],o['candidate'][vi]);assert c['delta_auc']>0;tr=joblib.load(p/f'fold{k}/transformer.joblib');report['oof']['folds'].append({'comparison':c,'feature_audit':feature_audit(tr,raw.iloc[fi])})
  out=ROOT/'research_artifacts/w3_tabm_values_full';rec=json.loads((out/'result.json').read_text());assert rec['status']=='complete' and rec['actual_epochs']==20 and rec['model_sha256']==sha(out/'model.pt') and rec['transformer_sha256']==sha(out/'transformer.joblib');tr=joblib.load(out/'transformer.joblib');report['full_feature_audit']=feature_audit(tr,raw);components=np.load(out/'test_components.npz');old=np.load(ROOT/'research_artifacts/gpu_value_v6_full/test_components.npz');assert np.array_equal(components['id'],test.id) and np.array_equal(old['candidate'],components['v6']);assert np.array_equal(components['candidate'],.75*components['v6']+.25*components['tabm']);csv=ROOT/'submission_tabm_value_v7.csv';b=pd.read_csv(csv);sample=pd.read_csv(ROOT/'data/sample_submission.csv');assert list(b)==['id','satisfaction'] and len(b)==299844 and b.id.equals(test.id) and b.id.equals(sample.id) and b.id.is_unique and np.isfinite(b.satisfaction).all() and b.satisfaction.between(0,1).all();diff=float(np.max(np.abs(b.satisfaction-components['candidate'])));assert diff<1e-14 and sha(csv)==rec['submission']['sha256'];report['csv']={'path':str(csv),'sha256':sha(csv),'rows':len(b),'bytes':csv.stat().st_size,'component_max_abs_diff':diff,'id_column_count_range_checks_pass':True}
  idx=np.random.default_rng(20261018).choice(len(test),1003,replace=False);arrays=tr.transform(test[list(raw)].iloc[idx]);model=load(out/'model.pt','cpu');model.eval()
  with torch.inference_mode():pred=model(torch.from_numpy(arrays[0]),torch.from_numpy(arrays[1])).softmax(-1).mean(1)[:,1].numpy()
  diff=float(np.max(np.abs(pred-components['tabm'][idx])));assert diff<2e-6;report['cpu_portability']={'sample_rows':len(idx),'seed':20261018,'max_abs_diff':diff,'all_saved_tensors_cpu':all(v.device.type=='cpu' for v in model.state_dict().values())}
 report.update(status='passed',completed_utc=now(),limitation='Reused development/confirmation/OOF labels; paired intervals are conditional and exclude model selection uncertainty.');dump(ROOT/'submission_tabm_value_v7_independent_audit.json',report);print(json.dumps(report,indent=2))
if __name__=='__main__':main()
